    @Test public void owner_unchecked_raw_assignment() throws Exception { this.program("public class Case{static class Outer<T>{T value;Outer(T x){value=x;}class Inner<U>{U inner;Inner(U x){inner=x;}T outer(){return value;}U get(){return inner;}}class Plain{T get(){return value;}}static class Nested<V>{V value;Nested(V x){value=x;}V get(){return value;}}}public static boolean main(){Outer o=new Outer(\"ok\");Outer.Inner raw=o.new Inner(2);Outer<String>.Inner<Integer> i=raw;return i.outer().equals(\"ok\") && i.get()==2;}}"); }
    @Test public void owner_lexical_generic_return() throws Exception { this.program("public class Case{static class Outer<T>{T value;Outer(T x){value=x;}class Inner<U>{U inner;Inner(U x){inner=x;}T outer(){return value;}U get(){return inner;}}class Plain{T get(){return value;}}static class Nested<V>{V value;Nested(V x){value=x;}V get(){return value;}}}static class Container<T>{Outer<T> o;Container(T x){o=new Outer<T>(x);}Outer<T>.Inner<Integer> make(){return o.new Inner<Integer>(2);}}public static boolean main(){Container<String> c=new Container<String>(\"ok\");return c.make().outer().equals(\"ok\");}}"); }
